def wash_image(arg):
    return {'images_detail': arg + '123'}

spec = {
    'images': Coalesce(
        [
            ('data.imageCategory', wash_image),
            ('data.anotherImagePath', wash_image)
        ]
    )
}
data = {
    'data': {
        'imageCategory': 'data1',
        'anotherImagePath': 'data2'
    }
}

result = glom(data, spec)
print(result)

